  const [summary,setSummary]=useState<Row[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(""),[detail,setDetail]=useState<{title:string;rows:Row[];cols:Array<[string,string]>}|null>(null);
  useEffect(()=>{if(mode!=="all")return;(async()=>{if(!supabase)return;setLoading(true);const [products,purchases,sales,batches]=await Promise.all([supabase.from("products").select("id,product_id,name,minimum_stock,sale_unit").eq("active",true).order("name"),supabase.from("purchase_items").select("product_id,quantity,free_quantity,rate,purchase_unit,sale_unit,units_per_purchase_unit,purchase_pack_qty,free_pack_qty,stock_unit_qty,purchase_rate_per_unit,batch:medicine_batches(batch_number),purchase:purchases(invoice_date,purchase_no,supplier_invoice_no,supplier:suppliers(name))"),supabase.from("sale_items").select("product_id,quantity,unit_rate,line_total,batch:medicine_batches(batch_number),sale:sales(sold_at,invoice_no,patient:patients(name,patient_id))"),supabase.from("medicine_batches").select("product_id,current_stock,purchase_rate,sale_unit,units_per_purchase_unit,purchase_unit")]);const first=[products,purchases,sales,batches].find(x=>x.error);if(first?.error){setError(first.error.message);setLoading(false);return}const purchaseRows=purchases.data||[],saleRows=sales.data||[],batchRows=batches.data||[];const rows=(products.data||[]).map((p:any)=>{const pr=purchaseRows.filter((x:any)=>x.product_id===p.id),sr=saleRows.filter((x:any)=>x.product_id===p.id),productBatches=batchRows.filter((x:any)=>x.product_id===p.id),live=productBatches.reduce((a:any,x:any)=>a+Number(x.current_stock),0),stockValue=productBatches.reduce((a:any,x:any)=>a+Number(x.current_stock||0)*Number(x.purchase_rate||0),0),purchaseQty=pr.reduce((a:any,x:any)=>a+Number(x.stock_unit_qty||x.quantity||0)+Number(x.free_quantity||0),0),saleQty=sr.reduce((a:any,x:any)=>a+Number(x.quantity||0),0);return{...p,purchaseQty,saleQty,stock:purchaseQty-saleQty,liveStock:live,stockValue,purchaseRows:pr,saleRows:sr}}).filter((r:any)=>r.purchaseQty||r.saleQty||r.liveStock);setSummary(rows);setError("");setLoading(false)})()},[mode]);
  if(mode!=="all"){const filtered=batchState.rows.filter(r=>mode==="low"?Number(r.current_stock)<=Number(r.product?.minimum_stock||0):mode==="expiry"?new Date(r.expiry_date)<=new Date(Date.now()+90*86400000):true).map(r=>{const units=Number(r.units_per_purchase_unit||1)||1,stock=Number(r.current_stock||0),packs=Math.floor(stock/units),loose=stock%units;return{...r,name:r.product?.name,product_id:r.product?.product_id,stock_display:`${stock} ${r.sale_unit||r.product?.sale_unit||"units"}`,pack_display:units>1?`${packs} ${r.purchase_unit||"pack"} + ${loose} ${r.sale_unit||"units"}`:`${stock} ${r.sale_unit||"units"}`}});return <><PageHead title={mode==="low"?"Low Stock":"Expiry Alerts"} subtitle="Live batch-wise alerts from current stock"/><div className="panel">{batchState.error?<ErrorBox text={batchState.error}/>:batchState.loading?<LoadingPanel/>:filtered.length?<DataTable columns={[["product_id","Product"],["name","Medicine"],["batch_number","Batch"],["expiry_date","Expiry"],["stock_display","Stock"],["pack_display","Pack equivalent"],["selling_rate","Rate"]]} rows={filtered}/>:<Empty/>}</div></>}
