  const chooseProduct=(id:string)=>{const p=products.find(x=>x.id===id),units=Number(p?.default_units_per_purchase_unit||1)||1,packRate=Number(p?.purchase_rate||0)*units;setItem({...item,product_id:id,purchase_unit:p?.purchase_unit||"strip",sale_unit:p?.sale_unit||"tablet",units_per_purchase_unit:units,purchase_rate:packRate,selling_rate:Number(p?.selling_rate||p?.mrp||0),mrp:Number(p?.mrp||0),gst_percent:Number(p?.gst_percent||0)})};
  const editRow=(index:number)=>{const x=items[index];setItem({product_id:x.product_id,batch_number:x.batch_number,expiry_date:x.expiry_date,quantity:x.quantity,free_quantity:x.free_quantity,gst_percent:x.gst_percent,purchase_rate:x.purchase_rate,mrp:x.mrp,selling_rate:x.selling_rate,units_per_purchase_unit:x.units_per_purchase_unit,purchase_unit:x.purchase_unit,sale_unit:x.sale_unit});setEditing(index)};
