  const load=useCallback(async()=>{if(!supabase)return;setLoading(true);const [s,p]=await Promise.all([supabase.from("deleted_sales_audit").select("id,invoice_no,bill_date,deleted_reason,deleted_at,audited,audited_at,deleted_by_user:profiles!deleted_sales_audit_deleted_by_fkey(full_name)").order("deleted_at",{ascending:false}).limit(100),supabase.from("deleted_purchases_audit").select("id,purchase_no,supplier_invoice_no,bill_date,deleted_reason,deleted_at,audited,audited_at,deleted_by_user:profiles!deleted_purchases_audit_deleted_by_fkey(full_name)").order("deleted_at",{ascending:false}).limit(100)]);setError(s.error?.message||p.error?.message||"");setSales(s.data||[]);setPurchases(p.data||[]);setLoading(false)},[]);
