  const render=(kind:"sale"|"purchase",rows:Row[])=>rows.length?<div className="data-wrap"><table className="data-table"><thead><tr><th>Bill</th><th>Date</th><th>Deleted by</th><th>Deleted at</th><th>Reason</th><th>Audit</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{kind==="sale"?r.invoice_no:`${r.purchase_no} / ${r.supplier_invoice_no}`}</td><td>{fmtDate(r.bill_date)}</td><td>{r.deleted_by_user?.full_name||"—"}</td><td>{fmtDate(r.deleted_at)}</td><td>{r.deleted_reason||"—"}</td><td>{r.audited?"Audited":"Not audited"}</td><td>{!r.audited&&profile.role==="admin"?<button className="table-edit" onClick={()=>mark(kind==="sale"?"deleted_sales_audit":"deleted_purchases_audit",r.id)}><CheckCircle2 size={14}/> Mark audited</button>:"—"}</td></tr>)}</tbody></table></div>:<Empty text={`No deleted ${kind} bills found.`}/>;
