function AccountPanel({title,subtitle,rows,cols,from,to,setFrom,setTo}:{title:string;subtitle:string;rows:Row[];cols:Array<[string,string]>;from:string;to:string;setFrom:(v:string)=>void;setTo:(v:string)=>void}){return <><PageHead title={title} subtitle={subtitle}/><div className="panel"><DateRange from={from} to={to} setFrom={setFrom} setTo={setTo}/>{rows.length?<DataTable columns={cols} rows={rows}/>:<Empty text="No account records found."/>}</div></>}
function AccountSummary({title,rows,from,to,setFrom,setTo}:{title:string;rows:Array<[string,number]>;from:string;to:string;setFrom:(v:string)=>void;setTo:(v:string)=>void}){return <><PageHead title={title} subtitle="Live account balances from clinic transactions"/><div className="panel"><DateRange from={from} to={to} setFrom={setFrom} setTo={setTo}/><section className="summary-strip account-summary">{rows.map(([label,value])=><Summary key={label} title={label} value={money(value)} hint="Selected period"/>)}</section></div></>}
function DailyClosing({profile,notify}:{profile:Profile;notify:(s:string)=>void}){const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form),opening=Number(f.get("opening_cash")),doctor=Number(f.get("doctor_fee_cash")||0),pharmacy=Number(f.get("pharmacy_cash_sales")||0),other=Number(f.get("other_income")||0),supplier=Number(f.get("supplier_payments")||0),expenses=Number(f.get("expenses")||0),refunds=Number(f.get("refunds")||0),expected=opening+doctor+pharmacy+other-supplier-expenses-refunds;const {error}=await supabase!.from("daily_closings").insert({organization_id:profile.organization_id,closing_date:f.get("closing_date"),opening_cash:opening,doctor_fee_cash:doctor,pharmacy_cash_sales:pharmacy,other_income:other,supplier_payments:supplier,expenses,refunds,expected_cash:expected,actual_cash:Number(f.get("actual_cash")),closed_by:profile.id});notify(error?.message||"Daily closing saved");if(!error)form.reset()};return <SimpleForm title="Daily Closing" subtitle="Store expected versus actual cash permanently" onSubmit={save}>{["closing_date","opening_cash","doctor_fee_cash","pharmacy_cash_sales","other_income","supplier_payments","expenses","refunds","actual_cash"].map(k=><Field key={k} name={k} label={k.replaceAll("_"," ")} type={k==="closing_date"?"date":"number"} required={k==="closing_date"||k==="opening_cash"||k==="actual_cash"}/>)}</SimpleForm>}
function SimpleForm({title,subtitle,onSubmit,children}:{title:string;subtitle:string;onSubmit:(e:FormEvent<HTMLFormElement>)=>void;children:React.ReactNode}){return <><PageHead title={title} subtitle={subtitle}/><div className="panel form-panel"><form onSubmit={onSubmit}><div className="form-grid">{children}</div><div className="form-actions"><button className="primary"><CheckCircle2 size={16}/> Save</button></div></form></div></>}
function ClinicManagement({notify}:{notify:(s:string)=>void}){
  const orgs=useRows("organizations","id,clinic_name,pharmacy_name,address,phone,gst_number,drug_license_number,active,created_at");
  const invites=useRows("user_invites","id,organization_id,username,full_name,role,active,accepted_at,created_at");
  const profiles=useRows("profiles","id,organization_id,username,full_name,role,active,created_at");
  const [saving,setSaving]=useState(false),[usernameStatus,setUsernameStatus]=useState(""),[editingClinic,setEditingClinic]=useState<Row|null>(null);
  const checkUsername=async(username:string)=>{if(!username.trim()){setUsernameStatus("");return}const {data,error}=await supabase!.rpc("username_available",{p_username:username});setUsernameStatus(error?error.message:data?"Username available":"Username already used")};
  const save=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);setSaving(true);const available=await supabase!.rpc("username_available",{p_username:f.get("admin_username")});if(available.error||!available.data){setSaving(false);notify(available.error?.message||"Username already used");return}const {error}=await supabase!.rpc("create_clinic_with_admin_username",{p_clinic_name:f.get("clinic_name"),p_admin_username:f.get("admin_username"),p_admin_password:f.get("admin_password"),p_admin_name:f.get("admin_name"),p_phone:f.get("phone")||null});setSaving(false);if(error){notify(error.message);return}notify("Clinic created. Admin can login with username and password.");form.reset();setUsernameStatus("");orgs.reload();invites.reload()};
  const adminProfile=editingClinic?profiles.rows.find(x=>x.organization_id===editingClinic.id&&x.role==="admin"):null;
  const adminInvite=editingClinic?invites.rows.find(x=>x.organization_id===editingClinic.id&&x.role==="admin"):null;
  const adminLogin=adminProfile||adminInvite;
  const saveClinicEdit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editingClinic)return;const f=new FormData(e.currentTarget);setSaving(true);const {error}=await supabase!.rpc("update_clinic_details",{p_organization_id:editingClinic.id,p_clinic_name:f.get("clinic_name"),p_phone:f.get("phone")||null,p_pharmacy_name:f.get("pharmacy_name")||null,p_address:f.get("address")||null,p_gst_number:f.get("gst_number")||null,p_drug_license_number:f.get("drug_license_number")||null,p_active:f.get("active")==="true"});if(error){setSaving(false);notify(error.message);return}if(String(f.get("admin_username")||"").trim()){const admin=adminProfile?await supabase!.rpc("update_profile_login_json",{p_payload:{profile_id:adminProfile.id,username:f.get("admin_username"),password:String(f.get("admin_password")||""),full_name:String(f.get("admin_name")||adminProfile.full_name||""),role:"admin",active:true}}):adminInvite?await supabase!.rpc("update_invite_login_json",{p_payload:{invite_id:adminInvite.id,username:f.get("admin_username"),password:String(f.get("admin_password")||""),full_name:String(f.get("admin_name")||adminInvite.full_name||""),role:"admin",active:true}}):{error:{message:"No admin login record found for this clinic. Create the clinic admin from Users & Roles first."}};if(admin.error){setSaving(false);notify(admin.error.message);return}}setSaving(false);notify("Clinic and admin login updated");setEditingClinic(null);orgs.reload();invites.reload();profiles.reload()};
  return <><PageHead title="Clinic Management" subtitle="Software owner area for creating and editing clinics"/><div className="admin-grid"><div className="panel form-panel"><h2 className="panel-title">Create clinic</h2><form onSubmit={save}><div className="form-grid"><Field name="clinic_name" label="Hospital / clinic name" required/><Field name="phone" label="Phone"/><Field name="admin_name" label="Clinic admin name" required/><label className="field"><span>Admin username *</span><input name="admin_username" required onBlur={e=>checkUsername(e.currentTarget.value)}/><small>{usernameStatus}</small></label><Field name="admin_password" label="Admin password" type="password" required/></div><div className="form-actions"><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<Plus size={16}/>} Create clinic</button></div></form></div><div className="panel"><h2 className="panel-title">Recent clinics</h2>{orgs.error?<ErrorBox text={orgs.error}/>:orgs.loading?<LoadingPanel/>:orgs.rows.length?<div className="user-list">{orgs.rows.map(org=><button type="button" key={org.id} className="user-row" onClick={()=>setEditingClinic(org)}><span><strong>{org.clinic_name}</strong><small>{org.phone||"No phone"} · {org.active?"Active":"Inactive"}</small></span><Pencil size={14}/></button>)}</div>:<Empty text="No clinics created yet."/>}</div></div><div className="panel admin-section"><h2 className="panel-title">Admin logins</h2>{invites.error?<ErrorBox text={invites.error}/>:invites.loading?<LoadingPanel/>:invites.rows.length?<DataTable columns={[["username","Username"],["full_name","Name"],["role","Role"],["active","Active"],["accepted_at","Accepted"]]} rows={invites.rows}/>:<Empty text="No login records found."/>}</div>{editingClinic&&<Modal title={`Edit clinic ${editingClinic.clinic_name}`} subtitle="Update clinic details and this clinic admin login" onClose={()=>setEditingClinic(null)}><form onSubmit={saveClinicEdit}><div className="form-grid"><Field name="clinic_name" label="Hospital / clinic name" required defaultValue={editingClinic.clinic_name}/><Field name="pharmacy_name" label="Pharmacy name" defaultValue={editingClinic.pharmacy_name}/><Field name="phone" label="Phone" defaultValue={editingClinic.phone}/><Field name="address" label="Address" defaultValue={editingClinic.address}/><Field name="gst_number" label="GST number" defaultValue={editingClinic.gst_number}/><Field name="drug_license_number" label="Drug license number" defaultValue={editingClinic.drug_license_number}/><label className="field"><span>Status</span><select name="active" defaultValue={String(editingClinic.active)}><option value="true">Active</option><option value="false">Inactive</option></select></label></div><div className="section-label">ADMIN LOGIN</div><div className="form-grid"><Field name="admin_name" label="Admin name" defaultValue={adminLogin?.full_name}/><label className="field"><span>Admin username *</span><input name="admin_username" required defaultValue={adminLogin?.username||""}/></label><Field name="admin_password" label="New admin password (optional)" type="password"/></div><div className="form-actions"><button type="button" className="secondary" onClick={()=>setEditingClinic(null)}>Cancel</button><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<CheckCircle2 size={16}/>} Update clinic</button></div></form></Modal>}</>}

function UsersPage({profile,notify}:{profile:Profile;notify:(s:string)=>void}){
  const users=useRows("profiles","id,username,full_name,role,mobile,active,created_at");
  const invites=useRows("user_invites","id,username,full_name,role,active,accepted_at,created_at");
  const doctors=useRows("doctors","id,doctor_id,name");
  const [selected,setSelected]=useState<Row|null>(null),[checked,setChecked]=useState<string[]>([]),[saving,setSaving]=useState(false),[usernameStatus,setUsernameStatus]=useState(""),[editingUser,setEditingUser]=useState<Row|null>(null),[editingInvite,setEditingInvite]=useState<Row|null>(null);
  useEffect(()=>{if(!selected||!supabase){setChecked([]);return}supabase.from("page_permissions").select("page_key").eq("profile_id",selected.id).then(({data})=>setChecked(data?.map(x=>x.page_key)||rolePages[selected.role]||["Dashboard"]))},[selected]);
  const checkUsername=async(username:string,current?:{profileId?:string;inviteId?:string})=>{if(!username.trim()){setUsernameStatus("");return}const {data,error}=await supabase!.rpc("username_available_for_user",{p_username:username,p_profile_id:current?.profileId||null,p_invite_id:current?.inviteId||null});setUsernameStatus(error?error.message:data?"Username available":"Username already used")};
  const createLogin=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);setSaving(true);const role=String(f.get("role"));const doctorId=String(f.get("doctor_id")||"");const available=await supabase!.rpc("username_available",{p_username:f.get("username")});if(available.error||!available.data){setSaving(false);notify(available.error?.message||"Username already used");return}const {error}=await supabase!.rpc("upsert_user_invite_username",{p_username:f.get("username"),p_password:f.get("password"),p_full_name:f.get("full_name"),p_role:role,p_doctor_id:doctorId||null});setSaving(false);if(error){notify(error.message);return}notify(`Login saved. User can sign in with username ${f.get("username")}.`);form.reset();setUsernameStatus("");invites.reload()};
  const saveUserEdit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editingUser)return;const f=new FormData(e.currentTarget);setSaving(true);const {error}=await supabase!.rpc("update_profile_login_json",{p_payload:{profile_id:editingUser.id,username:f.get("username"),password:String(f.get("password")||""),full_name:String(f.get("full_name")||""),role:String(f.get("role")),active:f.get("active")==="true"}});setSaving(false);if(error){notify(error.message);return}notify("User login updated");setEditingUser(null);setUsernameStatus("");users.reload();invites.reload()};
  const saveInviteEdit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editingInvite)return;const f=new FormData(e.currentTarget);setSaving(true);const {error}=await supabase!.rpc("update_invite_login_json",{p_payload:{invite_id:editingInvite.id,username:f.get("username"),password:String(f.get("password")||""),full_name:String(f.get("full_name")||""),role:String(f.get("role")),active:f.get("active")==="true"}});setSaving(false);if(error){notify(error.message);return}notify("Login record updated");setEditingInvite(null);setUsernameStatus("");invites.reload()};
  const toggle=(page:string)=>setChecked(p=>p.includes(page)?p.filter(x=>x!==page):[...p,page]);
  const savePermissions=async()=>{if(!selected)return;setSaving(true);const {error}=await supabase!.rpc("set_page_permissions",{p_profile_id:selected.id,p_pages:checked});setSaving(false);notify(error?.message||"Page permissions updated")};
  if(profile.role!=="admin"&&profile.role!=="software_owner")return <><PageHead title="Users & Roles" subtitle="Only clinic admins can manage logins and page permissions"/><ErrorBox text="Admin access is required for this page."/></>;
  return <><PageHead title="Users & Roles" subtitle="Create, edit and migrate clinic username/password logins"/><div className="admin-grid"><div className="panel form-panel"><h2 className="panel-title">Create login access</h2><div className="auth-message login-help">Existing email users can be edited from Active users to assign username/password.</div><form onSubmit={createLogin}><div className="form-grid"><Field name="full_name" label="Full name" required/><label className="field"><span>Username *</span><input name="username" required onBlur={e=>checkUsername(e.currentTarget.value)}/><small>{usernameStatus}</small></label><Field name="password" label="Password" type="password" required/><label className="field"><span>Role *</span><select name="role" required defaultValue="doctor">{roleOptions.map(r=><option key={r} value={r}>{r.replace("_"," ")}</option>)}</select></label><label className="field"><span>Link doctor profile</span><select name="doctor_id"><option value="">Not a doctor login</option>{doctors.rows.map(d=><option key={d.id} value={d.id}>{d.doctor_id} - {d.name}</option>)}</select></label></div><div className="form-actions"><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<UserRoundPlus size={16}/>} Save login access</button></div></form></div><div className="panel"><h2 className="panel-title">Active users</h2>{users.error?<ErrorBox text={users.error}/>:users.loading?<LoadingPanel/>:users.rows.length?<div className="user-list">{users.rows.map(user=><div key={user.id} className={`user-row ${selected?.id===user.id?"selected":""}`} onClick={()=>setSelected(user)}><span><strong>{user.full_name}</strong><small>{user.username||"needs username"} · {user.role.replace("_"," ")} · {user.active?"Active":"Inactive"}</small></span><button type="button" className="table-edit" onClick={e=>{e.stopPropagation();setEditingUser(user);setUsernameStatus("")}}><Pencil size={14}/> Edit</button></div>)}</div>:<Empty text="No users found."/>}</div></div>{selected&&<div className="panel admin-section"><div className="permission-head"><div><h2 className="panel-title">Page access for {selected.full_name}</h2><p>Select only the pages this login should see in the sidebar.</p></div><button className="primary" onClick={savePermissions} disabled={saving}>{saving?<LoaderCircle className="spin"/>:<CheckCircle2 size={16}/>} Save permissions</button></div><div className="permission-grid">{allPageLabels.map(page=><label key={page} className="permission-check"><input type="checkbox" checked={checked.includes(page)} onChange={()=>toggle(page)}/><span>{page}</span></label>)}</div></div>}<div className="panel admin-section"><h2 className="panel-title">Pending / accepted access records</h2>{invites.error?<ErrorBox text={invites.error}/>:invites.loading?<LoadingPanel/>:invites.rows.length?<div className="user-list">{invites.rows.map(invite=><button type="button" key={invite.id} className="user-row" onClick={()=>{setEditingInvite(invite);setUsernameStatus("")}}><span><strong>{invite.full_name}</strong><small>{invite.username||"needs username"} · {invite.role.replace("_"," ")} · {invite.active?"Active":"Inactive"} · {invite.accepted_at?"Accepted":"Pending"}</small></span><Pencil size={14}/></button>)}</div>:<Empty text="No login access records found."/>}</div>{editingUser&&<Modal title={`Edit user ${editingUser.full_name}`} subtitle="Assign or change username/password for an existing active user" onClose={()=>setEditingUser(null)}><form onSubmit={saveUserEdit}><div className="form-grid"><Field name="full_name" label="Full name" required defaultValue={editingUser.full_name}/><label className="field"><span>Username *</span><input name="username" required defaultValue={editingUser.username||""} onBlur={e=>checkUsername(e.currentTarget.value,{profileId:editingUser.id})}/><small>{usernameStatus}</small></label><Field name="password" label="New password (optional)" type="password"/><label className="field"><span>Role *</span><select name="role" required defaultValue={editingUser.role}>{roleOptions.map(r=><option key={r} value={r}>{r.replace("_"," ")}</option>)}</select></label><label className="field"><span>Status</span><select name="active" defaultValue={String(editingUser.active)}><option value="true">Active</option><option value="false">Inactive</option></select></label></div><div className="form-actions"><button type="button" className="secondary" onClick={()=>setEditingUser(null)}>Cancel</button><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<CheckCircle2 size={16}/>} Update user</button></div></form></Modal>}{editingInvite&&<Modal title={`Edit login ${editingInvite.full_name}`} subtitle="Edit pending or accepted login record. Password is changed only when entered." onClose={()=>setEditingInvite(null)}><form onSubmit={saveInviteEdit}><div className="form-grid"><Field name="full_name" label="Full name" required defaultValue={editingInvite.full_name}/><label className="field"><span>Username *</span><input name="username" required defaultValue={editingInvite.username||""} onBlur={e=>checkUsername(e.currentTarget.value,{inviteId:editingInvite.id})}/><small>{usernameStatus}</small></label><Field name="password" label="New password (optional)" type="password"/><label className="field"><span>Role *</span><select name="role" required defaultValue={editingInvite.role}>{roleOptions.map(r=><option key={r} value={r}>{r.replace("_"," ")}</option>)}</select></label><label className="field"><span>Status</span><select name="active" defaultValue={String(editingInvite.active)}><option value="true">Active</option><option value="false">Inactive</option></select></label></div><div className="form-actions"><button type="button" className="secondary" onClick={()=>setEditingInvite(null)}>Cancel</button><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<CheckCircle2 size={16}/>} Update login</button></div></form></Modal>}</>}

function ReportPage({title}:{title:string}){const maps:Record<string,[string,Array<[string,string]>]>={Reports:["sales",[["invoice_no","Invoice"],["sold_at","Date"],["pharmacy_revenue","Pharmacy revenue"],["doctor_fee","Consultation revenue"],["grand_total","Collection"]]],Settings:["organizations",[["clinic_name","Clinic"],["pharmacy_name","Pharmacy"],["phone","Phone"],["gst_number","GST"],["currency","Currency"]]]};const m=maps[title]||["notifications",[["created_at","Date"],["kind","Type"],["title","Notification"],["read_at","Read"]]];const x=useRows(m[0] as string,"*");return <List title={title} subtitle="Live Supabase records" state={x} cols={m[1] as Array<[string,string]>}/>}

function Field({name,label,type="text",required,textarea,defaultValue}:{name:string;label:string;type?:string;required?:boolean;textarea?:boolean;defaultValue?:string|number|null}){const isRequired=required&&name!=="symptoms";return <label className="field"><span>{label}{isRequired&&<b> *</b>}</span>{textarea?<textarea name={name} required={isRequired} defaultValue={defaultValue??""}/>:<input name={name} type={type} required={isRequired} defaultValue={defaultValue??""} step={type==="number"?"0.01":undefined}/>}</label>}
function SelectField({name,label,rows,text,value,onChange,empty}:{name:string;label:string;rows:Row[];text:(r:Row)=>string;value?:string;onChange?:(s:string)=>void;empty?:string}){
  const [internal,setInternal]=useState(value||""),[query,setQuery]=useState(""),[open,setOpen]=useState(false);
  const selectedValue=value!==undefined?value:internal;
  const selected=rows.find(r=>r.id===selectedValue);
  const display=selected?text(selected):"";
  const shown=query||display;
  const matches=rows.filter(r=>text(r).toLowerCase().includes(shown.trim().toLowerCase())).slice(0,30);
  const choose=(row:Row|null)=>{const next=row?.id||"";if(value===undefined)setInternal(next);onChange?.(next);setQuery(row?text(row):"");setOpen(false)};
  useEffect(()=>{if(value!==undefined){setInternal(value||"");if(!value)setQuery("")}},[value]);
  useEffect(()=>{if(selected)setQuery(text(selected));else if(!selectedValue)setQuery("")},[selectedValue,rows.length]);
  return <label className="field"><span>{label}</span><div className="patient-combobox searchable-select"><input type="hidden" name={name} value={selectedValue}/><div className="search-box patient-history-search"><Search size={15}/><input value={shown} onFocus={()=>setOpen(true)} onBlur={()=>setTimeout(()=>setOpen(false),160)} onKeyDown={e=>{if(e.key==="Enter"&&open&&matches.length>0&&!selected){choose(matches[0])}}} onChange={e=>{setQuery(e.currentTarget.value);if(selectedValue){if(value===undefined)setInternal("");onChange?.("")}setOpen(true)}} placeholder={empty||"Search and select"} autoComplete="off" role="combobox" aria-expanded={open}/></div>{open&&<div className="patient-listbox" role="listbox">{empty&&<button type="button" role="option" aria-selected={!selectedValue} key="empty-option" onMouseDown={e=>e.preventDefault()} onClick={()=>choose(null)}><strong>{empty}</strong><span>Clear selection</span></button>}{matches.length?matches.map(row=><button type="button" role="option" aria-selected={row.id===selectedValue} key={row.id} onMouseDown={e=>e.preventDefault()} onClick={()=>choose(row)}><strong>{text(row)}</strong></button>):<div className="patient-list-empty">No matching record found</div>}</div>}</div></label>
}

function PatientHistorySimple({profile,notify}:{profile:Profile;notify:(s:string)=>void}){
  const {rows:patients}=useRows("patients","id,patient_id,name,mobile");
  const {rows:doctors}=useRows("doctors","id,name");
  const [id,setId]=useState("");
  const [patientQuery,setPatientQuery]=useState("");
  const [patientListOpen,setPatientListOpen]=useState(false);
  const [selectedImageFiles,setSelectedImageFiles]=useState<File[]>([]);
  const [refresh,setRefresh]=useState(0);
  const [saving,setSaving]=useState(false);
  const [history,setHistory]=useState<Row[]>([]);
  const [urls,setUrls]=useState<Record<string,string>>({});
  const [loading,setLoading]=useState(false);
  const [viewer,setViewer]=useState<{images:Array<{src:string;name:string}>;index:number}|null>(null);
  const [zoom,setZoom]=useState(1);
  const [pan,setPan]=useState({x:0,y:0});
  const [drag,setDrag]=useState<{x:number;y:number;startX:number;startY:number}|null>(null);

  useEffect(()=>{
    if(!id||!supabase){setHistory([]);setUrls({});return}
    setLoading(true);
    supabase.from("consultations").select("*,doctor:doctors(name),prescription_attachments(id,storage_path,file_name,content_type)").eq("patient_id",id).order("visited_at",{ascending:false}).then(async({data})=>{
      const records=data||[];
      setHistory(records);
      const attachments=records.flatMap(r=>r.prescription_attachments||[]);
      const pairs=await Promise.all(attachments.map(async(a:Row)=>{
        const {data:signed}=await supabase!.storage.from("prescriptions").createSignedUrl(a.storage_path,3600);
        return [a.id,signed?.signedUrl||""];
      }));
      setUrls(Object.fromEntries(pairs));
      setLoading(false);
    });
  },[id,refresh]);

  const save=async(e:FormEvent<HTMLFormElement>)=>{
    e.preventDefault();
    if(!id||!doctors.length)return;
    if(!selectedImageFiles.length){notify("Take or select at least one prescription image.");return}
    const form=e.currentTarget;
    const values=new FormData(form);
    const files=selectedImageFiles;
    setSaving(true);
    const {data,error}=await supabase!.from("consultations").insert({
      organization_id:profile.organization_id,
      patient_id:id,
      doctor_id:doctors[0].id,
      doctor_fee:Number(values.get("doctor_fee")||0),
      follow_up_date:values.get("follow_up_date")||null,
      created_by:profile.id
    }).select("id").single();
    if(error){setSaving(false);notify(error.message);return}
    let uploaded=0;
    for(const file of files){
      const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,"-");
      const path=`${profile.organization_id}/${id}/${data.id}/${Date.now()}-${safe}`;
      const {error:uploadError}=await supabase!.storage.from("prescriptions").upload(path,file,{contentType:file.type,upsert:false});
      if(uploadError){notify(`Fee saved, but ${file.name} failed: ${uploadError.message}`);continue}
      const {error:metaError}=await supabase!.from("prescription_attachments").insert({organization_id:profile.organization_id,patient_id:id,consultation_id:data.id,storage_path:path,file_name:file.name,content_type:file.type,size_bytes:file.size,uploaded_by:profile.id});
      if(!metaError)uploaded++;
    }
    await supabase!.from("patients").update({last_visit_at:new Date().toISOString()}).eq("id",id);
    setSaving(false);
    notify(`Doctor fee and ${uploaded} prescription image${uploaded===1?"":"s"} saved`);
    form.reset();
    setSelectedImageFiles([]);
    setRefresh(v=>v+1);
  };

  const patientLabel=(patient:Row)=>`${patient.patient_id} — ${patient.name}${patient.mobile?` — ${patient.mobile}`:""}`;
  const patientMatches=patients.filter(patient=>[patient.patient_id,patient.name,patient.mobile].some(value=>String(value||"").toLowerCase().includes(patientQuery.trim().toLowerCase()))).slice(0,20);
  const choosePatient=(patient:Row)=>{setPatientQuery(patientLabel(patient));setId(patient.id);setPatientListOpen(false)};
  const historyImages=history.flatMap(r=>(r.prescription_attachments||[]).filter((a:Row)=>a.content_type?.startsWith("image/")).map((a:Row)=>({id:a.id,src:urls[a.id],name:a.file_name}))).filter(x=>x.src);
  const resetViewerMotion=()=>{setZoom(1);setPan({x:0,y:0});setDrag(null)};
  const openViewer=(id:string)=>{const index=Math.max(0,historyImages.findIndex(x=>x.id===id));setViewer({images:historyImages,index});resetViewerMotion()};
  const closeViewer=()=>{setViewer(null);setDrag(null)};
  const changeZoom=(next:number)=>{setZoom(Math.max(1,Math.min(4,next)));if(next<=1)setPan({x:0,y:0})};
  const moveViewer=(step:number)=>{setViewer(v=>v?{...v,index:(v.index+step+v.images.length)%v.images.length}:v);resetViewerMotion()};
  const activeImage=viewer?.images[viewer.index];

  return <>
    <PageHead title="Patient History" subtitle="Add doctor fee, follow-up date and prescription images"/>
    <div className="panel history-entry">
      <label className="field">
        <span>Select patient</span>
        <div className="patient-combobox">
          <div className="search-box patient-history-search"><Search size={15}/><input value={patientQuery} onFocus={()=>setPatientListOpen(true)} onBlur={()=>setTimeout(()=>setPatientListOpen(false),160)} onChange={e=>{setPatientQuery(e.target.value);setId("");setPatientListOpen(true)}} placeholder="Search by patient ID, name or mobile number" autoComplete="off" role="combobox" aria-expanded={patientListOpen} aria-controls="patient-history-listbox"/></div>
          {patientListOpen&&<div className="patient-listbox" id="patient-history-listbox" role="listbox">{patientMatches.length?patientMatches.map(patient=><button type="button" role="option" aria-selected={patient.id===id} key={patient.id} onMouseDown={e=>e.preventDefault()} onClick={()=>choosePatient(patient)}><strong>{patient.patient_id} · {patient.name}</strong><span>{patient.mobile||"No mobile number"}</span></button>):<div className="patient-list-empty">No matching patient found</div>}</div>}
        </div>
      </label>
      {patientQuery&&!id&&<div className="patient-search-hint">Choose a patient from the matching list.</div>}
      {id&&(!doctors.length?<Empty text="Add at least one doctor before saving patient history."/>:<form onSubmit={save}>
        <div className="form-grid"><Field name="doctor_fee" label="Doctor fee" type="number" required/><Field name="follow_up_date" label="Follow-up date" type="date"/></div>
        <div className="prescription-actions">
          <label className="prescription-action"><Camera size={22}/><strong>Take photo</strong><span>Press again to add another camera photo</span><input type="file" accept="image/*" capture="environment" onChange={e=>{const added=Array.from(e.target.files||[]);setSelectedImageFiles(current=>[...current,...added]);e.target.value=""}}/></label>
          <label className="prescription-action"><Paperclip size={22}/><strong>Choose images</strong><span>Select multiple images from files or gallery</span><input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={e=>{const added=Array.from(e.target.files||[]);setSelectedImageFiles(current=>[...current,...added]);e.target.value=""}}/></label>
        </div>
        {selectedImageFiles.length>0&&<div className="selected-images"><strong>{selectedImageFiles.length} image{selectedImageFiles.length===1?"":"s"} ready to upload</strong>{selectedImageFiles.map((file,index)=><span key={`${file.name}-${file.lastModified}-${index}`}>{index+1}. {file.name}</span>)}</div>}
        <div className="form-actions"><button className="primary" disabled={saving}>{saving?<LoaderCircle className="spin"/>:<CheckCircle2 size={16}/>} Add to patient history</button></div>
      </form>)}
    </div>
    <div className="panel history-list"><h2>Complete patient history</h2>{loading?<LoadingPanel/>:history.length?<div className="timeline">{history.map(r=><div className="timeline-item" key={r.id}><span>{fmtDate(r.visited_at)}</span><div><h3>{r.doctor?.name||"Doctor"} · Doctor fee {money(r.doctor_fee)}</h3>{r.follow_up_date&&<p><b>Follow-up date:</b> {fmtDate(r.follow_up_date)}</p>}{r.symptoms&&<p><b>Symptoms:</b> {r.symptoms}</p>}{r.diagnosis&&<p><b>Diagnosis:</b> {r.diagnosis}</p>}{r.clinical_notes&&<p><b>Clinical notes:</b> {r.clinical_notes}</p>}{r.prescription_notes&&<p><b>Prescription:</b> {r.prescription_notes}</p>}{r.prescription_attachments?.length>0&&<div className="prescription-gallery full-images">{r.prescription_attachments.map((a:Row)=>a.content_type?.startsWith("image/")?<button type="button" className="prescription-image-full image-open" key={a.id} onClick={()=>openViewer(a.id)}><img src={urls[a.id]} alt={a.file_name}/><span>{a.file_name}</span></button>:<a className="prescription-file" key={a.id} href={urls[a.id]} target="_blank" rel="noreferrer"><Paperclip/><span>{a.file_name}</span></a>)}</div>}</div></div>)}</div>:<Empty text={id?"No history found. Add the first fee and image above.":"Select a patient to view history."}/>}</div>
    {viewer&&activeImage&&<div className="image-viewer" role="dialog" aria-modal="true" aria-label={activeImage.name}>
      <div className="image-viewer-bar"><strong>{activeImage.name}</strong><div><button type="button" onClick={()=>moveViewer(-1)}>‹</button><span>{viewer.index+1}/{viewer.images.length}</span><button type="button" onClick={()=>moveViewer(1)}>›</button><button type="button" onClick={()=>changeZoom(zoom-.5)}>-</button><span>{Math.round(zoom*100)}%</span><button type="button" onClick={()=>changeZoom(zoom+.5)}>+</button><button type="button" onClick={closeViewer}><X size={18}/></button></div></div>
      <div className="image-stage" onDoubleClick={()=>changeZoom(zoom===1?2:1)} onPointerDown={e=>{(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);setDrag({x:e.clientX,y:e.clientY,startX:pan.x,startY:pan.y})}} onPointerMove={e=>{if(drag&&zoom>1)setPan({x:drag.startX+e.clientX-drag.x,y:drag.startY+e.clientY-drag.y})}} onPointerUp={e=>{if(drag&&zoom===1){const dx=e.clientX-drag.x;if(Math.abs(dx)>60)moveViewer(dx<0?1:-1)}setDrag(null)}} onPointerCancel={()=>setDrag(null)}>
        <button type="button" className="image-nav prev" onClick={()=>moveViewer(-1)}>‹</button>
        <img src={activeImage.src} alt={activeImage.name} style={{transform:`translate(${pan.x}px, ${pan.y}px) scale(${zoom})`}} draggable={false}/>
        <button type="button" className="image-nav next" onClick={()=>moveViewer(1)}>›</button>
      </div>
      <div className="image-viewer-help">Swipe left/right for next image. Double tap to zoom. Drag image after zoom.</div>
    </div>}
  </>;
}

function FollowUpAlerts(){
  const today=()=>{const now=new Date(),offset=now.getTimezoneOffset();return new Date(now.getTime()-offset*60000).toISOString().slice(0,10)};
  const [date,setDate]=useState(today);
  const [rows,setRows]=useState<Row[]>([]);
  const [urls,setUrls]=useState<Record<string,string>>({});
  const [selected,setSelected]=useState("");
  const [loading,setLoading]=useState(false);
  const [error,setError]=useState("");

  useEffect(()=>{
    if(!supabase)return;
    setLoading(true);setError("");setSelected("");
    supabase.from("consultations").select("id,visited_at,follow_up_date,prescription_notes,patient:patients(id,patient_id,name,mobile),prescription_attachments(id,storage_path,file_name,content_type)").eq("follow_up_date",date).order("visited_at",{ascending:false}).then(async({data,error:queryError})=>{
      if(queryError){setError(queryError.message);setRows([]);setLoading(false);return}
      const records=data||[];
      setRows(records);
      const attachments=records.flatMap(row=>row.prescription_attachments||[]);
      const pairs=await Promise.all(attachments.map(async(attachment:Row)=>{
        const {data:signed}=await supabase!.storage.from("prescriptions").createSignedUrl(attachment.storage_path,3600);
        return [attachment.id,signed?.signedUrl||""];
      }));
      setUrls(Object.fromEntries(pairs));
      setLoading(false);
    });
  },[date]);

  return <>
    <PageHead title="Follow-up Alerts" subtitle="Patients scheduled for follow-up on the selected date"/>
    <div className="panel followup-toolbar"><label className="field"><span>Follow-up date</span><input type="date" value={date} onChange={event=>setDate(event.target.value||today())}/></label></div>
    <div className="panel followup-results">
      <h2>{rows.length} patient{rows.length===1?"":"s"} for {fmtDate(`${date}T00:00:00`)}</h2>
      {error?<ErrorBox text={error}/>:loading?<LoadingPanel/>:rows.length?<div className="followup-list">{rows.map(row=>{
        const patient=row.patient||{};
        const open=selected===row.id;
        return <article className="followup-card" key={row.id}>
          <div className="followup-patient-row">
            <button className="followup-patient" type="button" onClick={()=>setSelected(open?"":row.id)}><strong>{patient.patient_id} · {patient.name}</strong><span>Last consultation: {fmtDate(row.visited_at)} · Click to {open?"hide":"show"} prescription</span></button>
            {patient.mobile?<a className="call-button" href={`tel:${String(patient.mobile).replace(/[^+\d]/g,"")}`}><Phone size={16}/> Call {patient.mobile}</a>:<span className="no-mobile">No mobile number</span>}
          </div>
          {open&&<div className="last-prescription"><h3>Last prescription</h3>{row.prescription_notes&&<p>{row.prescription_notes}</p>}{row.prescription_attachments?.length?<div className="prescription-gallery full-images">{row.prescription_attachments.map((attachment:Row)=>attachment.content_type?.startsWith("image/")?<div className="prescription-image-full" key={attachment.id}><img src={urls[attachment.id]} alt={attachment.file_name}/><span>{attachment.file_name}</span></div>:<a className="prescription-file" key={attachment.id} href={urls[attachment.id]} target="_blank" rel="noreferrer"><Paperclip/><span>{attachment.file_name}</span></a>)}</div>:!row.prescription_notes&&<p>No prescription attachment found.</p>}</div>}
        </article>;
      })}</div>:<Empty text="No patients have a follow-up on this date."/>}
    </div>
  </>;
}
function Modal({title,subtitle,onClose,children}:{title:string;subtitle:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-wrap"><div className="modal"><div className="modal-head"><div><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-btn" onClick={onClose}><X size={19}/></button></div>{children}</div></div>}
function LoadingPanel(){return <div className="loading-panel"><LoaderCircle className="spin"/> Loading database records…</div>}





